{
  "title": "functions.expression.Special",
  "description": "Predefined expression behaviors that require no user-authored code.",
  "anyOf": [
    {
      "title": "Input",
      "description": "Returns the params input as-is.",
      "type": "string",
      "enum": [
        "input"
      ]
    },
    {
      "title": "Output",
      "description": "Returns the params output as-is.",
      "type": "string",
      "enum": [
        "output"
      ]
    },
    {
      "title": "TaskOutputL1Normalized",
      "description": "L1-normalizes the output. Scalar/Err pass through.\nVector: L1 normalize. Vectors: L1 normalize each.",
      "type": "string",
      "enum": [
        "task_output_l1_normalized"
      ]
    },
    {
      "title": "TaskOutputWeightedSum",
      "description": "Weighted sum of the output. Vector → Scalar. Vectors → Vector.",
      "type": "string",
      "enum": [
        "task_output_weighted_sum"
      ]
    },
    {
      "title": "InputItemsOutputLength",
      "description": "Returns the length of input['items'] as u64",
      "type": "string",
      "enum": [
        "input_items_output_length"
      ]
    },
    {
      "title": "InputItemsOptionalContextSplit",
      "description": "Splits an input containing items and optionally context into multiple inputs",
      "type": "string",
      "enum": [
        "input_items_optional_context_split"
      ]
    },
    {
      "title": "InputItemsOptionalContextMerge",
      "description": "Merges multiple inputs containing items and optionally context into a single input",
      "type": "string",
      "enum": [
        "input_items_optional_context_merge"
      ]
    }
  ]
}

{
  "title": "agent.completions.message.UserMessageExpression",
  "description": "Expression variant of [`UserMessage`] for dynamic content.",
  "type": "object",
  "properties": {
    "content": {
      "description": "The message content expression.\n\nA value that can be either a literal or an expression.\n\nThis allows Function definitions to mix static values with dynamic\nexpressions. During compilation, expressions are evaluated while\nliteral values pass through unchanged.\n\n# Example\n\nLiteral value:\n```json\n\"hello world\"\n```\n\nJMESPath expression:\n```json\n{\"$jmespath\": \"input.greeting\"}\n```\n\nStarlark expression:\n```json\n{\"$starlark\": \"input['greeting']\"}\n```",
      "anyOf": [
        {
          "title": "Expression",
          "description": "An expression (JMESPath or Starlark) to evaluate.",
          "$ref": "functions.expression.Expression"
        },
        {
          "title": "Value",
          "description": "A literal value.",
          "$ref": "agent.completions.message.RichContentExpression"
        }
      ]
    },
    "name": {
      "description": "Optional name expression.",
      "anyOf": [
        {
          "description": "A value that can be either a literal or an expression.\n\nThis allows Function definitions to mix static values with dynamic\nexpressions. During compilation, expressions are evaluated while\nliteral values pass through unchanged.\n\n# Example\n\nLiteral value:\n```json\n\"hello world\"\n```\n\nJMESPath expression:\n```json\n{\"$jmespath\": \"input.greeting\"}\n```\n\nStarlark expression:\n```json\n{\"$starlark\": \"input['greeting']\"}\n```",
          "anyOf": [
            {
              "title": "Expression",
              "description": "An expression (JMESPath or Starlark) to evaluate.",
              "$ref": "functions.expression.Expression"
            },
            {
              "title": "Value",
              "description": "A literal value.",
              "type": "string"
            }
          ]
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    }
  }
}
